FAULT 0 );

CREATE TABLE FUTTER ( ID INTEGER PRIMARY KEY AUTO_INCREMENT NOT NULL, ID_SILO INTEGER NOT NULL, SILONUMMER INTEGER NOT NULL DEFAULT 0, HERDENR INTEGER NOT NULL DEFAULT 0, ID_PERSON INTEGER NOT NULL DEFAULT 0, LIEFERDATUM VARCHAR(25) NOT NULL DEFAULT '0001-01-01', LIEFERMENGE DECIMAL(10, 2) NOT NULL DEFAULT 0, PREISDT DECIMAL(18, 2) NOT NULL DEFAULT 0, RABATTPROZ DECIMAL(10, 2) NOT NULL DEFAULT 0, NETTO DECIMAL(18, 2) NOT NULL DEFAULT 0, BRUTTO DECIMAL(18, 2) NOT NULL DEFAULT 0, MWSTPROZ DECIMAL(6, 2) NOT NULL DEFAULT 0, MWSTKZ CHAR(1) NOT NULL DEFAULT 'x', DATUM VARCHAR(25) NOT NULL DEFAULT '0001-01-01', ZEITSTEMPEL VARCHAR(50) NOT NULL DEFAULT '', ID_FUTTERSORTEN INTEGER NOT NULL DEFAULT 0, AW INTEGER NOT NULL DEFAULT 0 );

