CREATE TABLE RASSE ( ID INTEGER PRIMARY KEY AUTO_INCREMENT NOT NULL, RASSE VARCHAR(20) NOT NULL DEFAULT '', AW INTEGER NOT NULL DEFAULT 0 );

CREATE TABLE SILO ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, SILONUMMER INTEGER NOT NULL DEFAULT 0, PERSONENNUMMER INTEGER NOT NULL DEFAULT 0, ID_LIEFERANT INTEGER NOT NULL DEFAULT 0, BEZEICHNUNG VARCHAR(30) NOT NULL DEFAULT '', INVENTURDATUMALT VARCHAR(25) NOT NULL DEFAULT '0001-01-01', INVENTURDATUMNEU VARCHAR(25) NOT NULL DEFAULT '0001-01-01', MAXFUELLMENGE INTEGER NOT NULL DEFAULT 0, MINFUELLMENGE INTEGER NOT NULL DEFAULT 0, INVENTURFUELLMENGE INTEGER NOT NULL DEFAULT 0, AW INTEGER NOT NULL DEFAULT 0 );

