CREATE TABLE DYNAMISCHE_SQL ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, BESCHREIBUNG TEXT NOT NULL, SQLSTATEMENT TEXT NOT NULL, KATEGORIE_KZ CHAR(1) NOT NULL DEFAULT 'x', GRUPPEN_KZ CHAR(1) NOT NULL DEFAULT 'x', TYP_KZ CHAR(1) NOT NULL DEFAULT 'x', TEMPLATE_NAME VARCHAR(191) NOT NULL DEFAULT '', PARAM_DEF VARCHAR(191) NOT NULL DEFAULT '', DETAIL_SQL TEXT NOT NULL, LINK_LOGIC VARCHAR(191) NOT NULL DEFAULT '', GROUP_FIELD VARCHAR(191) NOT NULL DEFAULT '', ROWS_PER_PAGE INTEGER NOT NULL DEFAULT 0, PAGE_ORIENTATION VARCHAR(191) NOT NULL DEFAULT 'P', SHOW_MASTER_GRID INTEGER NOT NULL DEFAULT 0, SHOW_DETAIL_GRID INTEGER NOT NULL DEFAULT 0, SYSTEM_KZ VARCHAR(191) NOT NULL DEFAULT '0', SQLSTATEMENT_NATIVE TEXT NOT NULL, DETAIL_SQL_NATIVE TEXT NOT NULL, ROOT_KZ CHAR(1) NOT NULL DEFAULT 'x', SUMMENZEILE VARCHAR(191) NOT NULL DEFAULT '', IST_SUMMENZEILE INTEGER NOT NULL DEFAULT 0 );

