CREATE TABLE IF NOT EXISTS BENUTZERPROFILE ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, PROFIL_KZ CHAR ( 1 ) NOT NULL UNIQUE, BESCHREIBUNG TEXT NOT NULL, F_DASHBOARD INTEGER NOT NULL DEFAULT 0, F_HERDEN_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_EINRICHTUNGEN_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_PERSONEN_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_BUCHUNGEN_ERFASSEN INTEGER NOT NULL DEFAULT 0, F_AUSWERTUNGEN_ANZEIGEN INTEGER NOT NULL DEFAULT 0, F_SQL_STRUKTUR_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_BENUTZER_PROFILE INTEGER NOT NULL DEFAULT 0, F_PARAMETER_EDITIEREN INTEGER NOT NULL DEFAULT 0, F_KOSTEN_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_TABELLEN_ANZEIGEN INTEGER NOT NULL DEFAULT 0, F_TEXTE_VERWALTEN INTEGER NOT NULL DEFAULT 0, F_SYSTEM_VERWALTUNG INTEGER NOT NULL DEFAULT 0, F_BACKUP_ERSTELLEN INTEGER NOT NULL DEFAULT 0 );

CREATE TABLE BENUTZER ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, USERNAME VARCHAR(191) NOT NULL UNIQUE, PASSWORT VARCHAR(191) NOT NULL, KLARNAME VARCHAR(191) NOT NULL DEFAULT '', ID_BENUTZER_PROFILE INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (ID_BENUTZER_PROFILE) REFERENCES BENUTZERPROFILE (ID) );

CREATE TABLE SHOWTV ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, TVNAME TEXT(30) NOT NULL DEFAULT '', SHOWIT INTEGER NOT NULL DEFAULT 0 );

CREATE TABLE FUTTERSORTEN ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, BEZEICHNUNG VARCHAR(191) NOT NULL DEFAULT 'x' );

CREATE TABLE VERKAUF ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, ID_EILAGERBUCHUNG INTEGER NOT NULL DEFAULT 0 UNIQUE, ID_BUCHUNG INTEGER NOT NULL DEFAULT 0, BUCHUNGSDATUM VARCHAR(191) NOT NULL DEFAULT '0001-01-01', MENGESMALL INTEGER NOT NULL DEFAULT 0 CHECK (MENGESMALL >= 0), MENGEMEDIUM INTEGER NOT NULL DEFAULT 0 CHECK (MENGEMEDIUM >= 0), MENGELARGE INTEGER NOT NULL DEFAULT 0 CHECK (MENGELARGE >= 0), MENGEXL INTEGER NOT NULL DEFAULT 0 CHECK (MENGEXL >= 0), PREISSMALL REAL NOT NULL DEFAULT 0.0 CHECK (PREISSMALL >= 0), PREISMEDIUM REAL NOT NULL DEFAULT 0.0 CHECK (PREISMEDIUM >= 0), PREISLARGE REAL NOT NULL DEFAULT 0.0 CHECK (PREISLARGE >= 0), PREISXL REAL NOT NULL DEFAULT 0.0 CHECK (PREISXL >= 0), GESAMTPREIS REAL NOT NULL DEFAULT 0.0 CHECK (GESAMTPREIS >= 0), BIO TINYINT(1) NOT NULL DEFAULT 0, VERBUCHT TINYINT(1) NOT NULL DEFAULT 0, CHARGE TEXT(25) NOT NULL DEFAULT '', RABATTPROZENT NUMERIC(5, 2) NOT NULL DEFAULT 0, FOREIGN KEY (ID_EILAGERBUCHUNG) REFERENCES EILAGERBUCHUNG (ID) ON DELETE CASCADE );

CREATE UNIQUE INDEX IF NOT EXISTS IDX_lagerbuchung ON EILAGERBUCHUNG (ID_BUCHUNG, ID_EILAGER, BUCHUNGSDATUM, KZ_LAGER);

CREATE TABLE IF NOT EXISTS SYSTEMSETTINGS (
    NAME VARCHAR(191) PRIMARY KEY,
    VALUE TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS USER_STATE (
    ID INTEGER PRIMARY KEY AUTO_INCREMENT,
    USERNAME VARCHAR(191) NOT NULL,
    `KEY` VARCHAR(191) NOT NULL,
    VALUE TEXT NOT NULL,
    UNIQUE(USERNAME, `KEY`)
);

CREATE TABLE IF NOT EXISTS AKTIONEN ( ID INTEGER PRIMARY KEY AUTO_INCREMENT, AKTIONEN_KZ CHAR(1), ID_USER INTEGER DEFAULT 0, AKTIONSDATUM VARCHAR(25) DEFAULT '0001-01-01', BEZEICHNUNG TEXT, INTERVALL_TAGE INTEGER DEFAULT 0, ANZAHL_INTERVALLE INTEGER DEFAULT 0, ERLEDIGT INTEGER DEFAULT 0, ID_USER_ERLEDIGT INTEGER DEFAULT 0, ERLEDIGT_AM VARCHAR(25) );
